import os, csv, json, re

BASE = os.path.join("storage", "shared", "agency_lab")
ANALYSES = os.path.join(BASE, "analyses")
CSV_DIR = os.path.join(ANALYSES, "csv")
MANIFEST = os.path.join(ANALYSES, "analysis_manifest_v1.json")

CANON_SUCC = os.path.join(CSV_DIR, "transgen_v0_1_successions.csv")
ALIAS_SUCC = os.path.join(CSV_DIR, "transgen_successions_v0_1.csv")

MEANS = os.path.join(CSV_DIR, "transgen_means_v0_1.csv")
MEANS_NORM = os.path.join(CSV_DIR, "transgen_means_v0_1_normalized.csv")

DENOM_CSV = os.path.join(BASE, "data", "transgen_config", "progressor_max_collective_reward_per_round.csv")

def read_csv(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

def write_csv(path, rows, fieldnames):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=fieldnames)
        w.writeheader()
        w.writerows(rows)

def copy_successions_alias():
    if os.path.exists(CANON_SUCC):
        rows = read_csv(CANON_SUCC)
        if rows:
            write_csv(ALIAS_SUCC, rows, fieldnames=list(rows[0].keys()))
            print("WROTE", ALIAS_SUCC, "rows=", len(rows))
            return 0
    # Fallback: derive from manifest if alias needed and canonical missing
    if os.path.exists(MANIFEST):
        try:
            man = json.load(open(MANIFEST, "r", encoding="utf-8"))
            # Parse divergence trend: [["G1->G2", 0.03], ...]
            div = {}
            for entry in man.get("metrics", {}).get("divergence_trend", []):
                try:
                    key, val = entry[0], float(entry[1])
                    m = re.match(r"^G?(\d+)->G?(\d+)$", str(key).strip())
                    if m:
                        a, b = int(m.group(1)), int(m.group(2))
                        div[(a, b)] = val
                except Exception:
                    pass
            c2f = {}
            src = {}
            for name, source in (("c2f_reported", "reported"), ("c2f_derived_from_means", "derived")):
                for entry in man.get("metrics", {}).get(name, []):
                    try:
                        key, val = entry[0], float(entry[1])
                        m = re.match(r"^G?(\d+)->G?(\d+)$", str(key).strip())
                        if m:
                            a, b = int(m.group(1)), int(m.group(2))
                            c2f[(a, b)] = val
                            src[(a, b)] = source
                    except Exception:
                        pass
            keys = sorted(set(div.keys()) | set(c2f.keys()))
            rows = []
            for a, b in keys:
                rows.append({
                    "from_generation": a,
                    "to_generation": b,
                    "divergence_score": div.get((a, b), ""),
                    "ceiling_to_floor_start": c2f.get((a, b), ""),
                    "source": src.get((a, b), "n/a"),
                })
            if rows:
                write_csv(ALIAS_SUCC, rows, fieldnames=list(rows[0].keys()))
                print("WROTE", ALIAS_SUCC, "rows=", len(rows), "(derived)")
                return 0
        except Exception as e:
            print("WARN derive_alias:", e)
    print("WARN no successions available to alias")
    return 0  # Non-fatal

def to_float(x):
    try:
        return float(x)
    except Exception:
        return None

def normalize_means():
    if not os.path.exists(MEANS):
        print("WARN means missing:", MEANS)
        return 0
    # Load denominators
    if not os.path.exists(DENOM_CSV):
        print("WARN denominators missing:", DENOM_CSV)
        return 0
    den_rows = read_csv(DENOM_CSV)
    gen_col = None
    denom_col = None
    if den_rows:
        # Heuristics for column names
        cols = list(den_rows[0].keys())
        for c in cols:
            if c.lower() in ("generation", "gen", "g"):
                gen_col = c
            lc = c.lower()
            if all(w in lc for w in ("max", "collective", "reward")) and "round" in lc:
                denom_col = c
        if denom_col is None and len(cols) >= 2:
            denom_col = cols[1]  # fallback second column
        if gen_col is None:
            gen_col = cols[0]
    denom = {}
    for r in den_rows:
        g = r.get(gen_col)
        d = to_float(r.get(denom_col))
        if g is None or d is None:
            continue
        try:
            denom[int(float(g))] = d
        except Exception:
            pass

    rows = read_csv(MEANS)
    # Heuristic for total_reward_mean column
    cols = list(rows[0].keys()) if rows else []
    trm_col = None
    for c in cols:
        if c.lower() == "total_reward_mean" or ("total" in c.lower() and "reward" in c.lower() and "mean" in c.lower()):
            trm_col = c
            break
    # Optional num_agents column
    na_col = None
    for c in cols:
        if c.lower() in ("num_agents", "agents", "n_agents"):
            na_col = c
            break

    out = []
    for r in rows:
        g = r.get("generation") or r.get("Generation") or r.get("gen") or r.get("Gen")
        try:
            gi = int(float(g))
        except Exception:
            continue
        trm = to_float(r.get(trm_col)) if trm_col else None
        den = denom.get(gi)
        norm = (trm / den) if (trm is not None and den not in (None, 0)) else ""
        na = r.get(na_col) if na_col else ""
        per_agent = (trm / float(na)) if (trm is not None and na not in ("", None) and float(na) > 0) else ""
        out.append({
            "generation": gi,
            "total_reward_mean": trm if trm is not None else "",
            "normalized_collective_reward_mean": norm,
            "num_agents": na,
            "per_agent_reward_mean": per_agent,
        })
    if out:
        write_csv(MEANS_NORM, out, fieldnames=list(out[0].keys()))
        print("WROTE", MEANS_NORM, "rows=", len(out))
    return 0

def main():
    os.makedirs(CSV_DIR, exist_ok=True)
    copy_successions_alias()
    normalize_means()
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
